select date_trunc('quarter', order_date) as quarter_start, count(case when channel = 'partner' then 1 end) as partner_count, sum(case when channel = 'store' then discount else 0 end) as store_discount, approx_percentile(shipping_fee, array(0.25, 0.5, 0.75)) as shipping_fee_quartiles, sort_array(collect_set(status)) as status_list, percentile_approx(shipping_fee, 0.9) as shipping_fee_p90, stddev_samp(shipping_fee) as shipping_fee_stddev from orders group by 1 having shipping_fee_p90 < 1000000
